package org.animallink.incident.api;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.http.converter.HttpMessageNotReadableException;
@RestControllerAdvice public class IncidentExceptionHandler { @ExceptionHandler(EventController.NotFound.class) ResponseEntity<?> n(Exception e){return ResponseEntity.status(404).body(new Error(code(e,"RESOURCE_NOT_FOUND"),"资源不存在"));}@ExceptionHandler(EventController.Unauthorized.class) ResponseEntity<?> u(Exception e){return ResponseEntity.status(401).body(new Error("UNAUTHORIZED","需要登录"));}@ExceptionHandler(EventController.Forbidden.class) ResponseEntity<?> f(Exception e){return ResponseEntity.status(403).body(new Error(code(e,"GOVERNANCE_REQUIRED"),"无权执行此操作"));}@ExceptionHandler(EventController.Conflict.class) ResponseEntity<?> c(Exception e){return ResponseEntity.status(409).body(new Error(code(e,"STATE_CONFLICT"),"当前资源状态不允许此操作"));}@ExceptionHandler(EventController.Dependency.class) ResponseEntity<?> d(Exception e){return ResponseEntity.status(503).body(new Error(code(e,"DEPENDENCY_UNAVAILABLE"),"依赖服务暂不可用"));}@ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class,HttpMessageNotReadableException.class}) ResponseEntity<?> b(Exception e){return ResponseEntity.badRequest().body(new Error(code(e,"VALIDATION_ERROR"),"请求参数无效"));}@ExceptionHandler(Exception.class) ResponseEntity<?> internal(Exception e){return ResponseEntity.status(500).body(new Error("INTERNAL_ERROR","服务器内部错误"));} private String code(Exception e,String fallback){String m=String.valueOf(e.getMessage());if(m.contains("ACTIVE_VOLUNTEER_REQUIRED"))return "ACTIVE_VOLUNTEER_REQUIRED";if(m.contains("EVENT_NOT_ELIGIBLE_FOR_CASE"))return "EVENT_NOT_ELIGIBLE_FOR_CASE";if(m.contains("Case 不存在"))return "CASE_NOT_FOUND";if(m.contains("Case 已被其他志愿者认领"))return "CASE_ALREADY_CLAIMED";if(m.contains("Event 不存在"))return "EVENT_NOT_FOUND";if(m.contains("已提交"))return "EVENT_DRAFT_FINALIZED";if(m.contains("草稿")&&!m.contains("来源服务"))return "EVENT_DRAFT_NOT_FOUND";if(m.contains("成员"))return "CAMPUS_MEMBERSHIP_REQUIRED";if(m.contains("状态不允许"))return "INVALID_EVENT_TRANSITION";if(m.contains("不接受 Evidence"))return "EVENT_NOT_ACCEPTING_EVIDENCE";if(m.contains("同一 Campus"))return "CROSS_CAMPUS_ANIMAL";if(m.contains("ACTIVE"))return "ANIMAL_NOT_ACTIVE";if(m.contains("来源无效"))return "INVALID_PROVENANCE";if(m.contains("MinIO"))return "MINIO_UNAVAILABLE";if(m.contains("identity-service"))return "IDENTITY_SERVICE_UNAVAILABLE";if(m.contains("animal-service"))return "ANIMAL_SERVICE_UNAVAILABLE";if(m.contains("来源服务"))return "INTELLIGENCE_SERVICE_UNAVAILABLE";if(m.contains("媒体")||m.contains("image/")||m.contains("video/"))return "INVALID_MEDIA";if(m.contains("location")||m.contains("latitude")||m.contains("longitude"))return "INVALID_LOCATION";return fallback;} record Error(String code,String message){} }
